function [y] = act_clamp(x, lo, hi)
%ACT_CLAMP  The engine's clamp: lo below lo, hi above hi, else x (a nan stays nan).
%   x: real[1] (passed a plain number)
%   lo: real[1] (passed a plain number)
%   hi: real[1] (passed a plain number)
%   returns y: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    y = 0;
    if (x < lo)
        y = lo;
    elseif (x > hi)
        y = hi;
    else
        y = x;
    end
end
